import os, json

workspace = "/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-6/play/users/u022/system/state/workspace/programs"
task_id = "task-2264bd4e"
json_file = os.path.join(workspace, f"{task_id}.json")

with open(json_file) as f:
    demos = json.load(f)

# Check all demos' pattern
for i, d in enumerate(demos):
    colors = sorted(set(cell for row in d['input'] for cell in row))
    lo, hi = colors[0], colors[1]

    # Count frequency
    counts = {}
    for row in d['input']:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    print(f"Demo {i}: colors={colors}, lo={lo}, hi={hi}")
    print(f"  counts: {counts}")

    # Check what lo and hi become
    lo_map = {}
    hi_map = {}
    for row_in, row_out in zip(d['input'], d['output']):
        for c_in, c_out in zip(row_in, row_out):
            if c_in == lo:
                lo_map.setdefault(c_out, 0)
                lo_map[c_out] += 1
            if c_in == hi:
                hi_map.setdefault(c_out, 0)
                hi_map[c_out] += 1

    print(f"  lo={lo} maps to: {dict(lo_map)}")
    print(f"  hi={hi} maps to: {dict(hi_map)}")
    print()

